def find_lca(root, p, q):
    def dfs(node):
        if node is None:
            return None
        # If current node is one of the targets, it could be the LCA
        if node.val == p or node.val == q:
            return node
        left = dfs(node.left)
        right = dfs(node.right)
        # Found targets on both sides: this node is the LCA
        if left and right:
            return node
        # Propagate the non-null result upward
        return left if left else right

    return dfs(root).val
